import pytest

from sales_dashboard.loader import daily_conversion_counts, dedupe_sessions, parse_session_log
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_conversion_rate_counts_none_as_not_converted():
    assert conversion_rate([{"converted": True}, {"converted": None}]) == 0.5
    assert conversion_rate([]) == 0.0


def test_parse_flags_whitespace_and_skipped_lines():
    lines = ["", "   ", "  # header", " x , 2 , 0 ", " y , 3 ,  "]
    assert parse_session_log(lines) == [
        {"id": "x", "day": 2, "converted": False},
        {"id": "y", "day": 3, "converted": None},
    ]


@pytest.mark.parametrize("invalid", ["x,1", "x,1,1,extra", "x,bad,0"])
def test_parse_errors_include_original_line_number(invalid):
    with pytest.raises(ValueError, match=r"\bline 4\b"):
        parse_session_log([" # comment", "x,1,1", " ", invalid])


def test_dedupe_keeps_last_record_per_id_then_sorts():
    events = parse_session_log(["b,9,1", "z,1,0", "b,2,0", "a,2,1"])
    assert dedupe_sessions(events) == [events[1], events[3], events[2]]


def test_daily_counts_include_gaps_and_exclude_outside_days():
    events = parse_session_log(["a,0,1", "b,2,1", "c,2,1", "d,3,0", "e,5,1"])
    assert daily_conversion_counts(events, 1, 4) == [0, 2, 0, 0]
    assert daily_conversion_counts(events, 4, 1) == []


@pytest.mark.parametrize("days, expected", [(0, 0), (2, 5), (4, 6)])
def test_trailing_window(days, expected):
    assert conversions_in_window([1, 2, 3], days) == expected


def test_summary_uses_pooled_rate_and_calendar_days():
    groups = {
        "a": parse_session_log(["x,1,1"]),
        "b": parse_session_log(["y,4,0", "z,4,1"]),
        "empty": [],
    }
    assert pooled_conversion_rate(groups) == 2 / 3
    assert campaign_summary(groups, 3) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert campaign_summary({"empty": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_group_reports_order_and_empty_groups():
    groups = {"z": [{"converted": True}], "b": [], "a": [{"converted": True}],
              "c": [{"converted": False}]}
    assert top_converting_groups(groups, 5) == ["a", "z", "c"]
    assert top_converting_groups(groups, 1) == ["a"]
    assert list(conversion_rate_by_group(groups).items()) == [
        ("a", 1.0), ("b", None), ("c", 0.0), ("z", 1.0)
    ]


@pytest.mark.parametrize("counts, expected", [([], 0), ([-1, 0], 0), ([2, 0, 1, 1, -1, 1], 2)])
def test_streak_counts_consecutive_positive_days(counts, expected):
    assert longest_conversion_streak(counts) == expected
